describe("Failure handling", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-invoc-ac5-");

    // Register an adapter that exits with error
    registerAdapter("failing-mock-acp", {
      command: "node",
